  const finishedMatch = { ...active, results, winnerSeed };
  let matches = replaceMatch(state.matches, state.activeMatch, finishedMatch);
  const nextIndex = state.activeMatch + 1;
  const nextPlan = tournamentMatchPlans(state.playerCount)[nextIndex];
  if (nextPlan) {
    const target = matches[nextIndex];
    if (target) {
      const players: [number | null, number | null] = [...target.players];
      const slot = nextPlan.sources[0] === state.activeMatch ? 0 : nextPlan.sources[1] === state.activeMatch ? 1 : -1;
