const SETUP_KEYS = ['format', 'names', 'playerCount', 'state', 'version'] as const;
const EVENT_KEYS = [
  'activeMatch',
  'format',
  'game',
  'matches',
  'phase',
  'playerCount',
  'players',
  'state',
  'turnIndex',
  'version',
] as const;
const PAST_KEYS = ['championSeed', 'matches', 'playerCount', 'players'] as const;

export function readTournamentSetup(value: unknown): TournamentSetup | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, SETUP_KEYS) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    value.state !== 'setup' ||
    !isPlayerCount(value.playerCount)
  )
    return null;
  const names = readDraftNames(value.names);
  return names ? { playerCount: value.playerCount, names } : null;
}

export function readTournamentState(value: unknown): TournamentState | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, EVENT_KEYS) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    value.state !== 'tournament' ||
    !isPlayerCount(value.playerCount) ||
    !isNonnegativeSafeInteger(value.activeMatch) ||
    (value.turnIndex !== 0 && value.turnIndex !== 1) ||
    !isTournamentPhase(value.phase) ||
    typeof value.game !== 'string'
  )
    return null;
  const players = readTournamentPlayers(value.players, value.playerCount);
  const matches = readTournamentMatches(value.matches, value.playerCount);
  const game = decodeSnapshot(value.game);
  if (!players || !matches || !game || value.activeMatch >= matches.length) return null;
  const active = matches[value.activeMatch];
  if (!active || active.players[0] === null || active.players[1] === null) return null;
  if (game.boardCode !== active.boardCode || game.size !== active.size) return null;
  if (!validMatchProgress(matches, value.activeMatch)) return null;
  if (!validCurrentTurn(value.phase, value.turnIndex, value.activeMatch, matches, game)) return null;
  return {
    playerCount: value.playerCount,
    players,
    matches,
    activeMatch: value.activeMatch,
    turnIndex: value.turnIndex,
    phase: value.phase,
    game,
  };
}

export function readPastTournament(value: unknown): PastTournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, PAST_KEYS) || !isPlayerCount(value.playerCount))
    return null;
  const players = readTournamentPlayers(value.players, value.playerCount);
  const matches = readTournamentMatches(value.matches, value.playerCount);
  if (!players || !matches || !isNonnegativeSafeInteger(value.championSeed)) return null;
  if (matches.some((match) => match.winnerSeed === null)) return null;
  const final = matches[matches.length - 1];
  if (!final || final.winnerSeed !== value.championSeed) return null;

import { encodeSnapshot } from '../snapshot.ts';
import { isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { SNAPSHOT_KEYS } from '../snapshot.ts';
import { TOURNAMENT_FORMAT, TOURNAMENT_FORMAT_VERSION } from './types.ts';
import { readTournamentSetup, readTournamentState } from './validation.ts';
import type { TournamentImport, TournamentSetup, TournamentState } from './types.ts';

export const TOURNAMENT_JSON_MAX_BYTES = 65_536;
const SETUP_KEYS = ['format', 'names', 'playerCount', 'state', 'version'] as const;
const EVENT_KEYS = ['activeMatch', 'format', 'game', 'matches', 'phase', 'playerCount', 'players', 'state', 'turnIndex', 'version'] as const;
const MATCH_KEYS = ['boardCode', 'id', 'number', 'players', 'results', 'round', 'size', 'winnerSeed'] as const;

export type TournamentDecodeResult = TournamentImport | {
  readonly kind: 'invalid';
  readonly message: string;
};

export function encodeTournament(setup: TournamentSetup, tournament: TournamentState | null): string {
  if (!tournament) {
    return JSON.stringify(
      {
        format: TOURNAMENT_FORMAT,
        names: [...setup.names],
        playerCount: setup.playerCount,
        state: 'setup',
        version: TOURNAMENT_FORMAT_VERSION,
      },
      null,
      2,
    );
  }
  return JSON.stringify(
    {
      activeMatch: tournament.activeMatch,
      format: TOURNAMENT_FORMAT,
      game: encodeSnapshot(tournament.game),
      matches: tournament.matches.map((match) => ({
        boardCode: match.boardCode,
        id: match.id,
        number: match.number,
        players: [...match.players],
        results: match.results.map((result) =>
          result ? { elapsedMs: result.elapsedMs, moves: result.moves } : null,
        ),
        round: match.round,
        size: match.size,
        winnerSeed: match.winnerSeed,
      })),
      phase: tournament.phase,
      playerCount: tournament.playerCount,
      players: tournament.players.map((player) => ({ name: player.name, seed: player.seed })),
      state: 'tournament',
      turnIndex: tournament.turnIndex,
      version: TOURNAMENT_FORMAT_VERSION,
    },
    null,
    2,
  );
}

export function decodeTournament(text: string): TournamentDecodeResult {
  const value = isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value)) return invalid();
  const unknown = findUnknownTournamentField(value);
  if (unknown) return invalid(`Unknown field: ${unknown}.`);
  if (value.format !== TOURNAMENT_FORMAT) return invalid();
  if (value.state === 'setup') {
    const setup = readTournamentSetup(value);
    return setup ? { kind: 'setup', setup } : invalid();
  }
  if (value.state === 'tournament') {
    const tournament = readTournamentState(value);
    return tournament ? { kind: 'tournament', tournament } : invalid();
  }
  return invalid();
}

function findUnknownTournamentField(root: Record<string, unknown>): string | null {
  const rootKeys =
    root.state === 'setup'
      ? SETUP_KEYS
      : root.state === 'tournament'
        ? EVENT_KEYS
        : [...SETUP_KEYS, ...EVENT_KEYS];
  const rootField = unknownField(root, rootKeys);
  if (rootField) return rootField;
  if (root.state !== 'tournament') return null;

  const snapshot = typeof root.game === 'string' ? parseJson(root.game) : undefined;
  const snapshotField = unknownField(snapshot, SNAPSHOT_KEYS);
  if (snapshotField) return snapshotField;
  if (isJsonObject(snapshot) && isJsonObject(snapshot.selection)) {
    const kind = snapshot.selection.kind;
    const selectionKeys =
      kind === 'closed'
        ? ['kind']
        : kind === 'one'
          ? ['kind', 'index']
          : kind === 'mismatch'
            ? ['kind', 'first', 'second', 'remainingMs']
            : ['kind', 'index', 'first', 'second', 'remainingMs'];
    const selectionField = unknownField(snapshot.selection, selectionKeys);
    if (selectionField) return selectionField;
  }

  if (Array.isArray(root.matches)) {
    for (const match of root.matches) {
      const matchField = unknownField(match, MATCH_KEYS);
      if (matchField) return matchField;
      if (!isJsonObject(match)) continue;
      const nestedField = findMatchChildUnknownField(match);
      if (nestedField) return nestedField;
    }
  }
  if (Array.isArray(root.players)) {
    for (const player of root.players) {
      const playerField = unknownField(player, ['name', 'seed']);
      if (playerField) return playerField;
    }
  }
  return null;
}

function findMatchChildUnknownField(match: Record<string, unknown>): string | null {
  if (Array.isArray(match.results)) {
    for (const result of match.results) {
      const resultField = unknownField(result, ['elapsedMs', 'moves']);
      if (resultField) return resultField;
    }
  }
  return null;
}

function unknownField(value: unknown, allowedKeys: readonly string[]): string | null {
  if (!isJsonObject(value)) return null;
  const allowed = new Set(allowedKeys);
  return Object.keys(value).find((key) => !allowed.has(key)) ?? null;
}

function invalid(message = 'Invalid tournament JSON.') {
  return { kind: 'invalid' as const, message };
}

import { useRef, useState } from 'react';
import { createTournament, nextTournamentMatch, nextTournamentTurn, startTournamentTurn, activateTournamentCard, toPastTournament } from '../competition/transitions.ts';
import { decodeTournament, encodeTournament } from '../competition/format.ts';
import { normalizePlayerNames, tournamentMatchPlans } from '../competition/rules.ts';
import { freshBoardCode } from './fresh-board.ts';
import {
  browserTournamentStore,
  readTournamentHistory,
  tournamentHistoryKey,
  writeTournamentHistory,
} from './tournament-storage.ts';
import { useTournamentClock } from './use-tournament-clock.ts';
import type { TournamentPlayerCount, TournamentSetup, TournamentState } from '../competition/types.ts';
import type { PastTournament } from '../competition/types.ts';

export function useTournament(active: boolean) {
  const [store] = useState(() => browserTournamentStore());
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [past, setPast] = useState<readonly PastTournament[]>(initialHistory.items);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const pastRef = useRef(past);
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const current = useRef(tournament);

  function commit(next: TournamentState | null): void {
    if (next === current.current) return;
    current.current = next;
    setTournament(next);
  }

  const clock = useTournamentClock(active, tournament, current, (next) => commit(next));

  function retainPast(record: PastTournament): void {
    const key = tournamentHistoryKey(record);
    const next = [record, ...pastRef.current.filter((item) => tournamentHistoryKey(item) !== key)].slice(
      0,
      10,
    );
    pastRef.current = next;
    setPast(next);
    setStorageAvailable(writeTournamentHistory(store, next));
  }

  function start(playerCount: TournamentPlayerCount, drafts: readonly string[]): string | null {
    const accepted = normalizePlayerNames(drafts, playerCount);
    if (!accepted.ok) return accepted.error;
    const usedCodes = new Set<string>();
    const boardCodes = tournamentMatchPlans(playerCount).map((plan) => {
      let code = freshBoardCode(plan.size);
      while (usedCodes.has(code)) code = freshBoardCode(plan.size);
      usedCodes.add(code);
      return code;
    });
    const next = createTournament(playerCount, accepted.names, boardCodes);
    if (!next) return 'Unable to start tournament.';
    clock.reset();
    commit(next);
    return null;
  }

  function startTurn(): void {
    const currentTournament = current.current;
    if (!currentTournament) return;
    clock.reset();
    commit(startTournamentTurn(currentTournament));
  }

  function activate(index: number): void {
    clock.synchronize();
    const previous = current.current;
    if (!previous) return;
    const next = activateTournamentCard(previous, index);
    commit(next);
    if (previous.phase !== 'finished' && next.phase === 'finished') {
      const record = toPastTournament(next);
      if (record) retainPast(record);
    }
  }

  function nextTurn(): void {
    const currentTournament = current.current;
    if (!currentTournament) return;
    clock.reset();
    commit(nextTournamentTurn(currentTournament));
  }

  function nextMatch(): void {
    const currentTournament = current.current;
    if (!currentTournament) return;
    clock.reset();
    commit(nextTournamentMatch(currentTournament));
  }

  function leave(): void {
    clock.reset();
    commit(null);
  }

  function exportJson(setup: TournamentSetup): string {
    clock.synchronize();
    return encodeTournament(setup, current.current);
  }

  function loadJson(text: string) {
    const loaded = decodeTournament(text);
    if (loaded.kind === 'invalid') return loaded;
    clock.reset();
    if (loaded.kind === 'setup') {
      commit(null);
    } else {
      commit(loaded.tournament);
      const record = toPastTournament(loaded.tournament);
      if (record) retainPast(record);
    }
    return loaded;
  }

  return {
    tournament,
    past,
    storageAvailable,
    start,
    startTurn,
    activate,
    nextTurn,
    nextMatch,
    leave,
    exportJson,
    loadJson,
    pauseClock: clock.synchronize,
  };
}

import { useEffect, useRef, useState } from 'react';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentExchange } from './TournamentExchange.tsx';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import type { TournamentPlayerCount, TournamentSetup as SetupData } from './types.ts';
import type { useTournament } from '../session/use-tournament.ts';
import '../controls/control.css';
import './tournament.css';

interface TournamentProps {
  readonly controller: ReturnType<typeof useTournament>;
  onReturnToGame(): void;
}

export function Tournament({ controller, onReturnToGame }: TournamentProps) {
  const [playerCount, setPlayerCount] = useState<TournamentPlayerCount>(4);
  const [names, setNames] = useState<readonly string[]>(() => Array.from({ length: 8 }, () => ''));
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  const heading = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    heading.current?.focus();
  }, []);

  function publish(message: string): void {
    setNotice(message);
    setAnnouncement((value) => value + 1);
  }

  function changeName(index: number, value: string): void {
    setNames((current) => current.map((name, currentIndex) => (currentIndex === index ? value : name)));
  }

  function start(): void {
    const error = controller.start(playerCount, names);
    if (error) publish(error);
    else publish('');
  }

  function startTurn(): void {
    controller.startTurn();
    publish('');
  }

  function nextTurn(): void {
    controller.nextTurn();
    publish('');
  }

  function nextMatch(): void {
    controller.nextMatch();
    publish('');
  }

  function exportTournament(): string {
    const setup: SetupData = { playerCount, names };
    const exported = controller.exportJson(setup);
    setJson(exported);
    publish('Tournament exported.');
    return exported;
  }

  function loadTournament(text: string): void {
    const loaded = controller.loadJson(text);
    if (loaded.kind === 'invalid') {
      publish(loaded.message);
      return;
    }
    if (loaded.kind === 'setup') {
      setPlayerCount(loaded.setup.playerCount);
      setNames(loaded.setup.names);
      publish('Tournament setup loaded.');
    } else {
      setPlayerCount(loaded.tournament.playerCount);
      setNames((current) =>
        current.map((_, index) => loaded.tournament.players[index]?.name ?? ''),
      );
      publish('Tournament loaded.');
    }
  }

  function returnToGame(): void {
    onReturnToGame();
  }

  const tournament = controller.tournament;
  return (
    <main className="tournament-screen">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} tabIndex={-1} className="tournament-screen-heading">
        Tournament
      </h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      {tournament ? (
        <>
          <TournamentPlay
            tournament={tournament}
            statusNotice={notice}
            announcement={announcement}
            onStartTurn={startTurn}
            onNextTurn={nextTurn}
            onNextMatch={nextMatch}
            onLeave={returnToGame}
            onBackToGame={returnToGame}
            onActivate={controller.activate}
          />
          <TournamentBracket players={tournament.players} matches={tournament.matches} />
        </>
      ) : (
        <>
          <div className="tournament-status">
            <p role="status" aria-live="polite" aria-atomic="true">
              <span key={announcement}>{notice}</span>
            </p>
          </div>
          <TournamentSetup
            playerCount={playerCount}
            names={names}
            onPlayerCountChange={setPlayerCount}
            onNameChange={changeName}
            onStart={start}
            onBack={returnToGame}
          />
        </>
      )}
      <TournamentExchange
        value={json}
        onChange={setJson}
        onExport={exportTournament}
        onLoad={loadTournament}
      />
      <TournamentHistory tournaments={controller.past} storageAvailable={controller.storageAvailable} />
    </main>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { StatusLabel } from '../status/status-labels.ts';
import { formatElapsed } from '../elapsed-time.ts';
import type { TournamentState } from './types.ts';

interface TournamentPlayProps {
  readonly tournament: TournamentState;
  readonly statusNotice: string;
  readonly announcement: number;
  onStartTurn(): void;
  onNextTurn(): void;
  onNextMatch(): void;
  onLeave(): void;
  onBackToGame(): void;
  onActivate(index: number): void;
}

export function TournamentPlay({
  tournament,
  statusNotice,
  announcement,
  onStartTurn,
  onNextTurn,
  onNextMatch,
  onLeave,
  onBackToGame,
  onActivate,
}: TournamentPlayProps) {
  const board = useRef<BoardFocus>(null);
  const leaveDialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);
  const [confirmLeave, setConfirmLeave] = useState(false);
  const previousPhase = useRef(tournament.phase);
  const match = tournament.matches[tournament.activeMatch];
  const seed = match?.players[tournament.turnIndex];
  const player = tournament.players.find((candidate) => candidate.seed === seed);
  const name = player?.name ?? 'Player';
  const final = tournament.matches[tournament.matches.length - 1];
  const champion = tournament.players.find((candidate) => candidate.seed === final?.winnerSeed);

  useEffect(() => {
    if (previousPhase.current === 'ready' && tournament.phase === 'playing') {
      board.current?.focusRemembered();
    }
    previousPhase.current = tournament.phase;
  }, [tournament.phase]);

  useEffect(() => {
    if (confirmLeave) {
      leaveDialog.current?.showModal();
      keepPlaying.current?.focus();
    }
  }, [confirmLeave]);

  if (!match) return null;
  const action =
    tournament.phase === 'ready'
      ? { label: 'Start turn', run: onStartTurn }
      : tournament.phase === 'between-turns'
        ? { label: 'Next turn', run: onNextTurn }
        : tournament.phase === 'between-matches'
          ? { label: 'Next match', run: onNextMatch }
          : tournament.phase === 'finished'
            ? { label: 'Back to game', run: onBackToGame }
            : null;
  const matchWinner = match.winnerSeed
    ? tournament.players.find((candidate) => candidate.seed === match.winnerSeed)
    : undefined;
  const showBoard = tournament.phase !== 'ready';
  const statusKind =
    tournament.phase === 'ready' || tournament.phase === 'playing'
      ? 'playing'
      : tournament.phase === 'between-turns'
        ? 'turn-complete'
        : tournament.phase === 'between-matches'
          ? 'match-complete'
          : 'champion';
  const statusText = statusNotice
    ? statusNotice
    : statusKind === 'playing'
      ? `Now playing: ${name}`
      : statusKind === 'turn-complete'
        ? `Turn complete: ${name}`
        : statusKind === 'match-complete'
          ? `Match winner: ${matchWinner?.name ?? 'Unknown'}`
          : `Champion: ${champion?.name ?? 'Unknown'}`;
  const statusKey = statusNotice
    ? `notice-${announcement}`
    : `${tournament.activeMatch}-${tournament.turnIndex}-${statusKind}`;

  function keepPlaying(): void {
    leaveDialog.current?.close();
    setConfirmLeave(false);
  }

  function leaveTournament(): void {
    leaveDialog.current?.close();
    setConfirmLeave(false);
    onLeave();
  }

  return (
    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Current match</h3>
      <p>Round: {match.round}</p>
      <div className="tournament-status">
        <p
          role="status"
          aria-live="polite"
          aria-atomic="true"
          className={tournament.phase === 'finished' && !statusNotice ? 'tournament-champion' : ''}
        >
          <span key={statusKey}>{statusText}</span>
        </p>
      </div>
      <p className="tournament-deal-code">Deal: {match.boardCode}</p>
      <div className="tournament-stats" aria-label="Current game results">
        <dl>
          <div>
            <dt>{StatusLabel.moves}</dt>
            <dd>{tournament.game.moves}</dd>
          </div>
          <div>
            <dt>{StatusLabel.pairs}</dt>
            <dd>
              {tournament.game.matched.length / 2}/{tournament.game.deck.length / 2}
            </dd>
          </div>
          <div>
            <dt>{StatusLabel.time}</dt>
            <dd>{formatElapsed(tournament.game.elapsedMs)}</dd>
          </div>
        </dl>
      </div>
      <div className="tournament-actions">
        {action && (
          <button type="button" className="control" onClick={action.run}>
            {action.label}
          </button>
        )}
        {tournament.phase !== 'finished' ? (
          <button type="button" className="control" onClick={() => setConfirmLeave(true)}>
            Leave tournament
          </button>
        ) : null}
      </div>
      {showBoard && (
        <>
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={`${match.id}-${tournament.turnIndex}`}
            game={tournament.game}
            activate={onActivate}
            ref={board}
          />
        </>
      )}
      <dialog
        ref={leaveDialog}
        className="tournament-confirm"
        aria-labelledby="leave-tournament-heading"
        onCancel={() => setConfirmLeave(false)}
      >
        <h2 id="leave-tournament-heading">Leave tournament?</h2>
        <p>The current tournament will stop.</p>
        <div className="tournament-actions">
          <button
            ref={keepPlaying}
            type="button"
            className="control"
            onClick={keepPlaying}
          >
            Keep playing
          </button>
          <button
            type="button"
            className="control"
            onClick={leaveTournament}
          >
            Leave
          </button>
        </div>
      </dialog>
    </section>
  );
}

import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { normalizePlayerNames, tournamentMatchPlans, winningSeed } from './rules.ts';
import type {
  TournamentMatch,
  TournamentPlayer,
  TournamentPlayerCount,
  TournamentResult,
} from './types.ts';

const PLAYER_KEYS = ['name', 'seed'] as const;
const MATCH_KEYS = ['boardCode', 'id', 'number', 'players', 'results', 'round', 'size', 'winnerSeed'] as const;
const RESULT_KEYS = ['elapsedMs', 'moves'] as const;

export function isPlayerCount(value: unknown): value is TournamentPlayerCount {
  return value === 4 || value === 8;
}

export function readTournamentPlayers(
  value: unknown,
  count: TournamentPlayerCount,
): TournamentPlayer[] | null {
  if (!Array.isArray(value) || value.length !== count) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const entry: unknown = value[index];
    if (!isJsonObject(entry) || !hasExactKeys(entry, PLAYER_KEYS)) return null;
    if (typeof entry.name !== 'string' || entry.seed !== index + 1) return null;
    players.push({ name: entry.name, seed: entry.seed });
  }
  const normalized = normalizePlayerNames(players.map((player) => player.name), count);
  return normalized.ok && normalized.names.every((name, index) => name === players[index]?.name)
    ? players
    : null;
}

export function readTournamentMatches(
  value: unknown,
  count: TournamentPlayerCount,
): TournamentMatch[] | null {
  const plans = tournamentMatchPlans(count);
  if (!Array.isArray(value) || value.length !== plans.length) return null;
  const matches: TournamentMatch[] = [];
  const codes = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const entry: unknown = value[index];
    const plan = plans[index];
    if (!plan || !isJsonObject(entry) || !hasExactKeys(entry, MATCH_KEYS)) return null;
    if (
      entry.id !== plan.id ||
      entry.number !== plan.number ||
      entry.round !== plan.round ||
      entry.size !== plan.size ||
      typeof entry.boardCode !== 'string'
    )
      return null;
    const parsed = parseBoardCode(entry.boardCode);
    const players = readNullablePair(entry.players, (seed) => isSeed(seed, count));
    const results = readNullablePair(entry.results, (result) => isTournamentResult(result, plan.size));
    const winnerSeed = entry.winnerSeed;
    if (!parsed || parsed.size !== plan.size || codes.has(entry.boardCode) || !players || !results)
      return null;
    if (winnerSeed !== null && !isSeed(winnerSeed, count)) return null;
    codes.add(entry.boardCode);
    matches.push({
      id: plan.id,
      number: plan.number,
      round: plan.round,
      size: plan.size,
      boardCode: entry.boardCode,
      players,
      results,
      winnerSeed,
    });
  }
  return validateMatchOutcomes(matches, plans, count) ? matches : null;
}

export function isSeed(value: unknown, count: TournamentPlayerCount): value is number {
  return isNonnegativeSafeInteger(value) && value >= 1 && value <= count;
}

function validateMatchOutcomes(
  matches: readonly TournamentMatch[],
  plans: ReturnType<typeof tournamentMatchPlans>,
  count: TournamentPlayerCount,
): boolean {
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const plan = plans[index];
    if (!match || !plan) return false;
    for (const slot of [0, 1] as const) {
      const source = plan.sources[slot];
      const expected = source === null ? plan.openingPlayers[slot] : matches[source]?.winnerSeed ?? null;
      if (match.players[slot] !== expected) return false;
      if (match.players[slot] === null && match.results[slot] !== null) return false;
    }
    if (match.results[1] !== null && match.results[0] === null) return false;
    const [firstSeed, secondSeed] = match.players;
    const [firstResult, secondResult] = match.results;
    if (firstResult !== null && secondResult !== null) {
      if (firstSeed === null || secondSeed === null) return false;
      if (match.winnerSeed !== winningSeed([firstSeed, secondSeed], [firstResult, secondResult])) return false;
    } else if (match.winnerSeed !== null) {
      return false;
    }
  }
  return matches.every((match) => match.players.every((seed) => seed === null || isSeed(seed, count)));
}

function readNullablePair<T>(
  value: unknown,
  read: (item: unknown) => item is T,
): readonly [T | null, T | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first: unknown = value[0];
  const second: unknown = value[1];
  if (first !== null && !read(first)) return null;
  if (second !== null && !read(second)) return null;
  return [first, second];
}

function isTournamentResult(value: unknown, size: number): value is TournamentResult {
  if (!isJsonObject(value) || !hasExactKeys(value, RESULT_KEYS)) return false;
  return (
    typeof value.moves === 'number' &&
    Number.isSafeInteger(value.moves) &&
    value.moves >= (size * size) / 2 &&
    value.moves <= MOVES_MAX &&
    typeof value.elapsedMs === 'number' &&
    Number.isFinite(value.elapsedMs) &&
    value.elapsedMs >= 0 &&
    value.elapsedMs <= ELAPSED_MAX_MS
  );
}

      ? { label: 'Next turn', run: onNextTurn }
      : tournament.phase === 'between-matches'
        ? { label: 'Next match', run: onNextMatch }
        : tournament.phase === 'finished'
          ? { label: 'Back to game', run: onBackToGame }
          : null;
const matchWinner = match.winnerSeed
  ? tournament.players.find((candidate) => candidate.seed === match.winnerSeed)
  : undefined;
const showBoard = tournament.phase !== 'ready';
const statusKind =
  tournament.phase === 'ready'
    ? 'ready'
    : tournament.phase === 'playing'
      ? 'playing'
    : tournament.phase === 'between-turns'
      ? 'turn-complete'
      : tournament.phase === 'between-matches'
        ? 'match-complete'
        : 'champion';
const statusText = statusNotice
  ? statusNotice
  : statusKind === 'ready'
    ? `Ready for: ${name}`
    : statusKind === 'playing'
      ? `Now playing: ${name}`
    : statusKind === 'turn-complete'
      ? `Turn complete: ${name}`
      : statusKind === 'match-complete'
        ? `Match winner: ${matchWinner?.name ?? 'Unknown'}`
        : `Champion: ${champion?.name ?? 'Unknown'}`;
const statusKey = statusNotice
  ? `notice-${announcement}`
  : `${tournament.activeMatch}-${tournament.turnIndex}-${statusKind}`;

function keepPlaying(): void {
  leaveDialog.current?.close();
  setConfirmLeave(false);
}

function leaveTournament(): void {
  leaveDialog.current?.close();

  return { ok: true, names };
}

export function tournamentMatchPlans(playerCount: TournamentPlayerCount): readonly MatchPlan[] {
  if (playerCount === 4) {
    return [
      {
        id: 'S1',
        number: 1,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [1, 4],
        sources: [null, null],
      },
      {
        id: 'S2',
        number: 2,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [2, 3],
        sources: [null, null],
      },
      {
        id: 'F1',
        number: 1,
        round: 'Final',
        size: 8,
        openingPlayers: [null, null],
        sources: [0, 1],
      },
    ];
  }
  return [
    { id: 'Q1', number: 1, round: 'Quarterfinal', size: 4, openingPlayers: [1, 8], sources: [null, null] },
    { id: 'Q2', number: 2, round: 'Quarterfinal', size: 4, openingPlayers: [4, 5], sources: [null, null] },
    { id: 'Q3', number: 3, round: 'Quarterfinal', size: 4, openingPlayers: [3, 6], sources: [null, null] },
    { id: 'Q4', number: 4, round: 'Quarterfinal', size: 4, openingPlayers: [2, 7], sources: [null, null] },
    { id: 'S1', number: 1, round: 'Semifinal', size: 6, openingPlayers: [null, null], sources: [0, 1] },
    { id: 'S2', number: 2, round: 'Semifinal', size: 6, openingPlayers: [null, null], sources: [2, 3] },
    { id: 'F1', number: 1, round: 'Final', size: 8, openingPlayers: [null, null], sources: [4, 5] },
  ];
}

// A lower move count wins, then a lower active time, then the higher seed (seed 1).
export function winningSeed(
  seeds: readonly [number, number],
  results: readonly [TournamentResult, TournamentResult],
): number {
  if (results[0].moves !== results[1].moves) {
    return results[0].moves < results[1].moves ? seeds[0] : seeds[1];
  }
  if (results[0].elapsedMs !== results[1].elapsedMs) {
    return results[0].elapsedMs < results[1].elapsedMs ? seeds[0] : seeds[1];
  }
  return Math.min(seeds[0], seeds[1]);
}
import { createGame, activateCard, advanceGame, isWon } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { tournamentMatchPlans, winningSeed } from './rules.ts';
import type {
  PastTournament,
  TournamentMatch,
  TournamentPlayerCount,
  TournamentResult,
  TournamentState,
} from './types.ts';

export function createTournament(
  playerCount: TournamentPlayerCount,
  names: readonly string[],
  boardCodes: readonly string[],
): TournamentState | null {
  const plans = tournamentMatchPlans(playerCount);
  if (names.length !== playerCount || boardCodes.length !== plans.length) return null;
  const players = names.map((name, index) => ({ name, seed: index + 1 }));
  const matches: TournamentMatch[] = [];
  const usedCodes = new Set<string>();
  for (let index = 0; index < plans.length; index += 1) {
    const plan = plans[index];
    const boardCode = boardCodes[index];
    if (!plan || !boardCode) return null;
    const parsed = parseBoardCode(boardCode);
    if (!parsed || parsed.size !== plan.size || usedCodes.has(boardCode)) return null;
    usedCodes.add(boardCode);
    matches.push({
      id: plan.id,
      number: plan.number,
      round: plan.round,
      size: plan.size,
      boardCode,
      players: plan.openingPlayers,
      results: [null, null],
      winnerSeed: null,
    });
  }
  const first = matches[0];
  if (!first) return null;
  return {
    playerCount,
    players,
    matches,
    activeMatch: 0,
    turnIndex: 0,
    phase: 'ready',
    game: createGame(first.boardCode),
  };
}

export function startTournamentTurn(state: TournamentState): TournamentState {
  return state.phase === 'ready' ? { ...state, phase: 'playing' } : state;
}

export function tickTournament(state: TournamentState, milliseconds: number): TournamentState {
  if (state.phase !== 'playing') return state;
  const game = advanceGame(state.game, milliseconds);
  return game === state.game ? state : { ...state, game };
}

export function activateTournamentCard(state: TournamentState, index: number): TournamentState {
  if (state.phase !== 'playing') return state;
  const game = activateCard(state.game, index);
  if (game === state.game) return state;
  if (!isWon(game)) return { ...state, game };

  const active = state.matches[state.activeMatch];
  if (!active) return state;
  const result: TournamentResult = { moves: game.moves, elapsedMs: game.elapsedMs };
  const results: [TournamentResult | null, TournamentResult | null] = [...active.results];
  results[state.turnIndex] = result;
  if (state.turnIndex === 0) {
    return { ...state, game, phase: 'between-turns', matches: replaceMatch(state.matches, state.activeMatch, { ...active, results }) };
  }

  const firstSeed = active.players[0];
  const secondSeed = active.players[1];
  const firstResult = results[0];
  const secondResult = results[1];
  if (firstSeed === null || secondSeed === null || !firstResult || !secondResult) return state;
  const winnerSeed = winningSeed([firstSeed, secondSeed], [firstResult, secondResult]);
  const finishedMatch = { ...active, results, winnerSeed };
  let matches = replaceMatch(state.matches, state.activeMatch, finishedMatch);
  const plans = tournamentMatchPlans(state.playerCount);
  const targetIndex = plans.findIndex((plan) => plan.sources.includes(state.activeMatch));
  const targetPlan = plans[targetIndex];
  const target = matches[targetIndex];
  if (targetPlan && target) {
    const players: [number | null, number | null] = [...target.players];
    const slot = targetPlan.sources[0] === state.activeMatch ? 0 : 1;
    players[slot] = winnerSeed;
    matches = replaceMatch(matches, targetIndex, { ...target, players });
  }
  const isFinal = state.activeMatch === matches.length - 1;
  return { ...state, game, matches, phase: isFinal ? 'finished' : 'between-matches' };
}

export function nextTournamentTurn(state: TournamentState): TournamentState {
  if (state.phase !== 'between-turns') return state;
  const match = state.matches[state.activeMatch];
  return match
    ? { ...state, turnIndex: 1, phase: 'ready', game: createGame(match.boardCode) }
    : state;
}

export function nextTournamentMatch(state: TournamentState): TournamentState {
  if (state.phase !== 'between-matches') return state;
  const activeMatch = state.activeMatch + 1;
  const match = state.matches[activeMatch];
  return match && match.players[0] !== null && match.players[1] !== null
    ? { ...state, activeMatch, turnIndex: 0, phase: 'ready', game: createGame(match.boardCode) }
    : state;
}

export function toPastTournament(state: TournamentState): PastTournament | null {
  if (state.phase !== 'finished') return null;
  const final = state.matches[state.matches.length - 1];
  return final?.winnerSeed === null || final?.winnerSeed === undefined
    ? null
    : {
        playerCount: state.playerCount,
        players: state.players,
        matches: state.matches,
        championSeed: final.winnerSeed,
      };
}

function replaceMatch(
  matches: readonly TournamentMatch[],
  index: number,
  match: TournamentMatch,
): TournamentMatch[] {
  return matches.map((current, currentIndex) => (currentIndex === index ? match : current));
}

