        number: 2,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [2, 3],
        sources: [null, null],
      },
      {
        id: 'F1',
        number: 1,
        round: 'Final',
        size: 8,
        openingPlayers: [null, null],
        sources: [0, 1],
      },
    ];
  }
  return [
    {
      id: 'Q1',
      number: 1,
      round: 'Quarterfinal',
      size: 4,
      openingPlayers: [1, 8],
      sources: [null, null],
    },
    {
